/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import * as Core from "../core/index.js";
import { clearCurrentUser, getCurrentUser, persistCurrentUser } from "../core/auth.js";
import { extractErrorMessage, getAuthHeader, handleUserAuthFailure, isAbortError, requestJson } from "../core/api.js";
import { getCurrentPageName, goTo, resolvePagePath, USER_HOME_PAGE, USER_LOGIN_PAGE } from "../core/routing.js";
import { hideLoader, showLoader } from "../ui/loader.js";
import { showMessage } from "../ui/toast.js";

export async function handleUserLogin() {
  const username = String(document.getElementById("username")?.value || "").trim().toLowerCase();
  const password = document.getElementById("password")?.value || "";

  if (!username || !password) {
    showMessage("Username and password are required.", "error");
    return;
  }

  showLoader("Checking credentials...");

  const wakeTimeout = window.setTimeout(() => {
    const loaderText = document.getElementById("loader-text");
    if (loaderText && loaderText.textContent === "Checking credentials...") {
      loaderText.textContent = "Waking up server (this can take a few seconds)...";
    }
  }, 4000);

  try {
    const result = await requestJson("/api/auth/login", {
      method: "POST",
      body: { username, password, HWID: "WEB-CLIENT" }
    });

    window.clearTimeout(wakeTimeout);

    if (!result.ok) {
      hideLoader();
      showMessage(extractErrorMessage(result.data, "Invalid credentials."), "error");
      return;
    }

    const token = result.data.token || result.data.Token || result.data.jwt || result.data.accessToken || "";
    const isExpired = result.data.IsExpired || false;
    const storedUser = persistCurrentUser({
      token,
      username: result.data.username,
      plan: result.data.plan,
      expiry: result.data.expiry,
      isExpired: isExpired
    });

    if (!storedUser) {
      hideLoader();
      showMessage("Login token is missing a valid role claim.", "error");
      return;
    }

    if (storedUser.role !== "User") {
      hideLoader();
      clearCurrentUser();
      showMessage("This account is not allowed on the user login page.", "error");
      return;
    }

    const loaderText = document.getElementById("loader-text");
    if (loaderText) loaderText.textContent = "Login successful. Redirecting...";
    goTo(USER_HOME_PAGE);
  } catch (err) {
    window.clearTimeout(wakeTimeout);
    hideLoader();
    showMessage(isAbortError(err) ? "Request timed out. Try again." : "Please Check Your Internet.", "error");
  }
}

export function handleLogout() {
  showLoader("Logging out...");
  window.setTimeout(() => {
    clearCurrentUser();
    hideLoader();
    showMessage("Logged out successfully.", "success");
    window.location.replace(resolvePagePath("index.html"));
  }, 700);
}

export async function handleChangePassword() {
  const currentUser = getCurrentUser();

  if (currentUser && currentUser.plan && currentUser.plan.toLowerCase() === "free") {
    showMessage("Free users cannot change password.", "error");
    return;
  }
  if (!currentUser || currentUser.role !== "User") {
    clearCurrentUser();
    window.location.replace(USER_LOGIN_PAGE);
    return;
  }

  const currentPassword = document.getElementById("currentPassword")?.value || "";
  const newPassword = document.getElementById("newPassword")?.value || "";

  if (!currentPassword || !newPassword) {
    showMessage("Current and new password are required.", "error");
    return;
  }

  if (newPassword.length < 3) {
    showMessage("New password must be at least 3 characters long.", "error");
    return;
  }

  if (currentPassword === newPassword) {
    showMessage("New password must be different from the current password.", "error");
    return;
  }

  showLoader("Updating password...");

  try {
    const result = await requestJson("/api/auth/change-password", {
      method: "POST",
      headers: getAuthHeader(),
      body: { currentPassword, newPassword }
    });

    hideLoader();

    if (handleUserAuthFailure(result.status)) return;
    if (!result.ok) {
      showMessage(extractErrorMessage(result.data, "Failed to change password."), "error");
      return;
    }

    showMessage("Password updated successfully.", "success");
    goTo(USER_HOME_PAGE);
  } catch (err) {
    hideLoader();
    showMessage(isAbortError(err) ? "Request timed out. Try again." : "Server error.", "error");
  }
}

export function bindUserForms() {
  const userLoginForm = document.getElementById("userLoginForm");
  if (userLoginForm) {
    userLoginForm.addEventListener("submit", (event) => {
      event.preventDefault();
      handleUserLogin();
    });
  }

  const changePasswordForm = document.getElementById("changePasswordForm");
  if (changePasswordForm) {
    changePasswordForm.addEventListener("submit", (event) => {
      event.preventDefault();
      handleChangePassword();
    });
  }
}

export function bindKeyboardShortcuts() {
  const page = getCurrentPageName();

  if (page === "Ulogin.html") {
    ["username", "password"].forEach((id) => {
      const input = document.getElementById(id);
      if (!input) return;
      input.addEventListener("keydown", (event) => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        handleUserLogin();
      });
    });
  }

  if (page === "change.html") {
    ["currentPassword", "newPassword"].forEach((id) => {
      const input = document.getElementById(id);
      if (!input) return;
      input.addEventListener("keydown", (event) => {
        if (event.key !== "Enter") return;
        event.preventDefault();
        handleChangePassword();
      });
    });
  }
}

export async function handleAdminLogin() {
  const username = String(document.getElementById("adminUsername")?.value || "").trim().toLowerCase();
  const password = document.getElementById("adminPassword")?.value || "";

  if (!username || !password) {
    Core.showMessage("Username and password are required.", "error");
    return;
  }

  Core.showLoader("Checking admin credentials...");

  try {
    const result = await Core.requestJson("/api/admin/login", {
      method: "POST",
      body: { username, password }
    });

    if (!result.ok) {
      Core.hideLoader();
      Core.showMessage(Core.extractErrorMessage(result.data, "Invalid admin credentials."), "error");
      return;
    }

    const token = result.data.token || result.data.Token || result.data.jwt || result.data.accessToken || "";
    const storedAdmin = Core.persistCurrentUser({
      token,
      username: result.data.username || result.data.Username || username,
      loginTime: Date.now()
    });

    if (!storedAdmin) {
      Core.hideLoader();
      Core.showMessage("Admin token is missing a valid role claim.", "error");
      return;
    }

    if (storedAdmin.role !== "Admin") {
      Core.hideLoader();
      Core.clearCurrentUser();
      Core.showMessage("This account is not authorized for admin access.", "error");
      return;
    }

    Core.setOwnerAccessCache(String(result.data.role || "").trim().toLowerCase() === "owner" || Boolean(result.data.isOwner));
    Core.hideLoader();
    Core.showMessage("Admin login successful.", "success");
    Core.goTo("Adash.html");
  } catch (err) {
    Core.hideLoader();
    Core.showMessage(Core.isAbortError(err) ? "Request timed out. Try again." : "Please Check Your Internet.", "error");
  }
}

export function bindAdminLoginForm() {
  const form = document.getElementById("adminLoginForm");
  if (form) {
    form.addEventListener("submit", (event) => {
      event.preventDefault();
      handleAdminLogin();
    });
  }

  ["adminUsername", "adminPassword"].forEach((id) => {
    const input = document.getElementById(id);
    if (!input) return;
    input.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      handleAdminLogin();
    });
  });
}
